CREATE TABLE IF NOT EXISTS bridge_meta (id INTEGER PRIMARY KEY CHECK(id=1), schema_version INTEGER NOT NULL, stopped INTEGER NOT NULL);
INSERT OR IGNORE INTO bridge_meta VALUES(1,1,0);
CREATE TABLE IF NOT EXISTS jobs (id TEXT PRIMARY KEY, body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS inbox (source TEXT NOT NULL, event_id TEXT NOT NULL, job_id TEXT NOT NULL, logical_id TEXT NOT NULL, hash TEXT NOT NULL, disposition TEXT NOT NULL, body TEXT NOT NULL, PRIMARY KEY(source,event_id));
CREATE TABLE IF NOT EXISTS logical_events (job_id TEXT NOT NULL, logical_id TEXT NOT NULL, hash TEXT NOT NULL, PRIMARY KEY(job_id,logical_id));
CREATE TABLE IF NOT EXISTS launch_intents (job_id TEXT PRIMARY KEY, request_id TEXT UNIQUE NOT NULL, body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS routine_locks (routine_id TEXT PRIMARY KEY, job_id TEXT UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS outbox (id TEXT PRIMARY KEY, job_id TEXT NOT NULL UNIQUE, body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS quarantine (id INTEGER PRIMARY KEY, body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS budgets (campaign TEXT NOT NULL, candidate TEXT NOT NULL, jobs INTEGER NOT NULL, launches INTEGER NOT NULL, PRIMARY KEY(campaign,candidate));
